import React, { useEffect, useMemo, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getSeller } from '../services/api';
import ProductSlider from '../components/ProductSlider';

export default function SellerPage() {
  const { id } = useParams();
  const [s, setS] = useState(null);

  useEffect(() => { (async () => setS(await getSeller(id)))(); }, [id]);

  if (!s) return <div className="loading">Cargando…</div>;

  const priceFmt = (n) =>
    typeof n === 'number' ? n.toLocaleString('es-AR', { maximumFractionDigits: 0 }) : '';

  // Un único grupo con todos los productos del vendedor
  const groups = useMemo(() => {
    const products = (s.products || []).map((p) => ({
      id: p.id,
      imageUrl: p.imageUrl,
      name: p.name || 'producto',
      priceLabel: typeof p.price !== 'undefined' ? `$ ${priceFmt(p.price)}` : '$',
    }));
    return [{ id: `seller-${s.id}-all`, products, variant: 'cards' }];
  }, [s]);

  const normalizePhone = (t) => String(t || '').replace(/[^\d]/g, '');
  const wa = normalizePhone(s.contactPhone);
  const waHref = wa ? `https://wa.me/54${wa}` : null;

  const goBack = () =>
    window.history.length > 1 ? window.history.back() : (window.location.href = '/');

  const banner = s.imageUrl || '';

  return (
    <div className="sp-wrap">
      {/* Hero con banner del seller */}
      <section
        className="sp-hero"
        style={banner ? { backgroundImage: `url(${banner})` } : {}}
        aria-label={s.name || 'LOCAL'}
      >
        <div className="sp-hero-layer">
          <div className="sp-badge">
            {/* Fondo amarillo al 50% detrás del logo (el logo sin opacidad) */}
            <img src="/logo.png" alt="Conecta Pinamar" className="sp-logo" />
          </div>
          <h1 className="sp-title">{(s.name || 'LOCAL').toLowerCase()}</h1>
        </div>
      </section>

      {/* Slider de productos */}
      <section className="sp-section">
        <ProductSlider id="seller-products" groups={groups} />
      </section>

      {/* Ubicación */}
      <section className="sp-section">
        <h2 className="sp-subtitle">ubicacion</h2>
        <div className="sp-map">
          <iframe
            title="mapa"
            src={`https://www.google.com/maps?q=${encodeURIComponent(s.location || 'Pinamar')}&output=embed`}
            loading="lazy"
            referrerPolicy="no-referrer-when-downgrade"
          />
        </div>
      </section>

      {/* Saber más */}
      <section className="sp-section">
        <h2 className="sp-subtitle">saber mas</h2>
        <div className="sp-social">
          <a className="sp-ico sp-ig" href={s.instagram || '#'} target="_blank" rel="noreferrer" aria-label="Instagram">
            <svg viewBox="0 0 24 24" width="34" height="34"><path fill="currentColor" d="M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5m0 2a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3H7m5 3a6 6 0 1 1 0 12 6 6 0 0 1 0-12m0 2.2A3.8 3.8 0 1 0 15.8 13 3.8 3.8 0 0 0 12 9.2M18 6.5a1 1 0 1 1-1 1 1 1 0 0 1 1-1Z"/></svg>
          </a>
          <a className="sp-ico sp-fb" href={s.facebook || '#'} target="_blank" rel="noreferrer" aria-label="Facebook">
            <svg viewBox="0 0 24 24" width="34" height="34"><path fill="currentColor" d="M22 12a10 10 0 1 0-11.5 9.9v-7H8v-3h2.5V9.5A3.5 3.5 0 0 1 14 6h3v3h-3a1 1 0 0 0-1 1V12H17l-.5 3h-2.5v7A10 10 0 0 0 22 12Z"/></svg>
          </a>
          {waHref && (
            <a className="sp-ico sp-wa" href={waHref} target="_blank" rel="noreferrer" aria-label="WhatsApp">
              <svg viewBox="0 0 24 24" width="34" height="34"><path fill="currentColor" d="M20.5 3.5A11.7 11.7 0 0 0 3.4 20.6L2 22l1.6-.4A11.7 11.7 0 0 0 12 23h.1A11.5 11.5 0 0 0 23.6 11.5 11.5 11.5 0 0 0 20.5 3.5m-8.4 17.1a9.5 9.5 0 0 1-4.8-1.3l-.3-.2-3 .8.8-2.9-.2-.3a9.6 9.6 0 0 1 14-11.3 9.6 9.6 0 0 1 5.4 8.6 9.5 9.5 0 0 1-9.5 9.5m5.2-6.8c-.3-.2-1.7-.8-2-.9s-.5-.2-.8.2-.9 1-1.1 1.1-.4.2-.7.1a7.8 7.8 0 0 1-2.3-1.4 8.5 8.5 0 0 1-1.6-2c-.2-.3 0-.4.1-.6l.5-.7.2-.4c.1-.2 0-.4 0-.5l-.9-2.2c-.2-.5-.4-.4-.6-.4h-.5a1 1 0 0 0-.8.4C5.6 8 5 8.7 5 9.8s1 2.4 1.1 2.6a10.5 10.5 0 0 0 3.9 3.9c.5.3 2.2.9 3.1 1.1h.7c.2 0 .5 0 .8-.3s1-1 1.2-1.4.2-.6.2-.7-.1-.4-.3-.5Z"/></svg>
            </a>
          )}
        </div>
      </section>

      {/* back button */}
      <button className="sp-back" onClick={goBack}>← volver a la pagina anterior</button>

      <style>{`
        :root{
          --cp-yellow:#F7D34A;
          --cp-text:#111;
          --cp-muted:#6b7280;
          --shadow:0 10px 30px rgba(0,0,0,.15);
          --border:#e9e9e9;
        }

        .loading{padding:32px;text-align:center}

        .sp-wrap{
          background:#fff;
          color:var(--cp-text);
          min-height:100dvh;
          display:flex;
          flex-direction:column;
          align-items:center;
        }

        /* HERO (banner = imagen del seller) */
        .sp-hero{
          position:relative;
          width:100%;
          min-height:210px;
          background:#ddd center/cover no-repeat;
          display:grid; place-items:center;
          padding:18px 16px 54px;
        }
        .sp-hero::after{
          content:""; position:absolute; inset:0;
          background:linear-gradient(180deg, rgba(0,0,0,.15), rgba(0,0,0,.35));
        }
        .sp-hero-layer{
          position:relative; z-index:1; width:100%; max-width:1100px;
          display:flex; flex-direction:column; align-items:center; gap:10px;
        }
        .sp-badge{
          background:rgba(247,211,74,.5); /* 50% sólo el fondo */
          padding:6px 10px; border-radius:12px; box-shadow:var(--shadow);
          display:flex; align-items:center; justify-content:center; height:72px;
        }
        .sp-logo{ height:72px; display:block; }
        .sp-title{
          margin:0; color:#fff; text-align:center;
          text-shadow:0 2px 8px rgba(0,0,0,.35);
          font:800 32px/1.05 system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,Cantarell,Noto Sans,sans-serif;
          letter-spacing:.5px; text-transform:lowercase;
        }

        .sp-section{ width:100%; max-width:1100px; padding:20px 16px; }
        .sp-subtitle{
          margin:0 0 12px 0; font-weight:900; font-size:32px; text-transform:lowercase;
        }

        /* mapa */
        .sp-map{ border:1px solid var(--border); border-radius:16px; overflow:hidden; box-shadow:var(--shadow); }
        .sp-map iframe{ width:100%; height:230px; border:0; display:block; }

        /* social */
        .sp-social{ display:flex; gap:14px; align-items:center; }
        .sp-ico{ width:54px; height:54px; border-radius:14px; display:grid; place-items:center; background:#fff; border:1px solid var(--border); box-shadow:var(--shadow); color:#111; text-decoration:none; }
        .sp-ico:hover{ transform:translateY(-1px); box-shadow:0 12px 26px rgba(0,0,0,.12); }
        .sp-ig{ color:#E1306C; } .sp-fb{ color:#1778F2; } .sp-wa{ color:#25D366; }

        .sp-back{
          display:inline-flex; align-items:center; gap:6px;
          margin:16px auto 28px; padding:0; background:transparent; border:0;
          color:#6b7280; font-size:12px; cursor:pointer;
        }
        .sp-back:hover{ text-decoration:underline; }

        @media (min-width:900px){
          .sp-hero{ min-height:270px; padding:26px 16px 86px; }
          .sp-title{ font-size:40px; }
          .sp-map iframe{ height:300px; }
        }
      `}</style>
    </div>
  );
}
